def is_Sum_Of_Powers_Of_Two(n):
    if n <= 0:
        return False
    total = 0
    power = 1
    while total <= n:
        if total + power == n:
            return True
        total += power
        if total == n:
            return True
        power *= 2
    return power >> 1 >= n
```

